const texto = $input.first().json.output;
if (!texto || typeof texto !== 'string') {
  throw new Error('O campo "output" nÃ£o foi encontrado, estÃ¡ vazio ou nÃ£o Ã© uma string.');
}

// Passo 1: Regex para domÃ­nios com mÃºltiplos sufixos
const domainRegex = /\b(?:(?!\d\.\d)(?:[a-zA-Z][\w-]*)\.)+(?:[a-zA-Z]{2,})(?:\.[a-zA-Z]{2,})?\b/g;

// Passo 2: Mascarar domÃ­nios trocando "." por "_DOT_"
let textoMascarado = texto.replace(domainRegex, m => m.replace(/\./g, '_DOT_'));

// Passo 3: Quebrar em linhas nÃ£o vazias
let linhas = textoMascarado
  .split('\n')
  .map(l => l.trim())
  .filter(l => l.length > 0);

// Passo 4: Transformar linhas em sentenÃ§as (sem quebrar âDra. Gabrielaâ)
const sentenceSplitRegex = /(?<!Dr\.)(?<!Dra\.)(?<=[.!?])\s+(?=[A-ZÃÃÃÃÃÃÃÃÃÃÃÃÃÃÃÃ])/;
let sentencas = [];
linhas.forEach(linha => {
  if (linha.startsWith('- ')) {
    sentencas.push(linha.slice(2).trim());
  }
  else if (/^[0-9]+\.\s+/.test(linha)) {
    sentencas.push(linha.replace(/^[0-9]+\.\s+/, '').trim());
  }
  else {
    sentencas.push(
      ...linha
        .split(sentenceSplitRegex)
        .map(p => p.trim())
        .filter(p => p.length > 0)
    );
  }
});

// Passo 5: Cortar sentenÃ§as > 300 chars sem quebrar palavras
const MAX_LENGTH = 300;
let resultados = [];
sentencas.forEach(s => {
  const t = s.trim();
  if (t.length <= MAX_LENGTH) {
    resultados.push(t);
  } else {
    let buffer = '';
    t.split(' ').forEach(p => {
      const tentativa = buffer ? `${buffer} ${p}` : p;
      if (tentativa.length > MAX_LENGTH) {
        resultados.push(buffer);
        buffer = p;
      } else {
        buffer = tentativa;
      }
    });
    if (buffer) resultados.push(buffer);
  }
});

// Passo 6: Reverter "_DOT_" para "."
let revertidos = resultados.map(r => r.replace(/_DOT_/g, '.'));

// Passo 7: Converter **texto** em *texto*
let ajustados = revertidos.map(r => r.replace(/\*\*(.*?)\*\*/g, '*$1*'));

// Passo 8: Retornar sÃ³ as partes de texto
return ajustados.map(parte => ({ json: { parte } }));

